INSERT INTO kencana_photo_album (photo_id, title, category, url, "desc", date, location, photographer, sort_order) VALUES
('1794382372209', 'BPBD KABUPATEN MALANG SERAHKAN BANTUAN UNTUK KORBAN KEBAKARAN DESA KETINDAN, DIDAMPINGI LANGSUNG CAMAT LAWANG', 'respons', 'https://lh3.googleusercontent.com/d/1XBVwYgbbvfNdxIf9ONK_YW11j9YeJhP7', 'Lawang, Senin, 12 Oktober 2026 — Badan Penanggulangan Bencana Daerah (BPBD) Kabupaten Malang menyerahkan bantuan kepada korban kebakaran rumah di Dusun Tegalrejo, Desa Ketindan, Kecamatan Lawang.
Penyerahan bantuan tersebut didampingi langsung oleh Camat Lawang, Nur Soleh Hidayat, S.STP., M.M., sebagai bentuk kehadiran pemerintah dalam memastikan korban mendapatkan perhatian dan bantuan yang dibutuhkan pasca musibah.', '12 Oktober 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 0),
('1794382227976', '📢 DINSOS KABUPATEN MALANG SALURKAN BANTUAN SOSIAL UNTUK KORBAN KEBAKARAN DI DESA KETINDAN', 'respons', 'https://lh3.googleusercontent.com/d/1Yw6OepblPJa-WqC4HOUADPMpXE4R-nMy', 'Lawang, Kamis, 2 Oktober 2026 — Dinas Sosial Kabupaten Malang menyalurkan bantuan sosial kepada korban kebakaran rumah di Dusun Tegalrejo, Desa Ketindan, Kecamatan Lawang.
Bantuan tersebut disalurkan langsung oleh Plt. Sekcam Lawang kepada korban, Bapak Sukirno, sebagai bentuk kepedulian dan kehadiran pemerintah untuk meringankan beban warga yang tertimpa musibah.
Sebelumnya, pada Selasa, 30 September 2026 sekitar pukul 12.00 WIB, telah terjadi kebakaran rumah di Dusun Tegalrejo, Desa Ketindan. Kebakaran diduga disebabkan oleh korsleting arus listrik. Kerugian ditaksir kurang lebih Rp 127.000.000,-.', '2 Oktober 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 1),
('1794382081815', 'Bupati Malang menghadiri kegiatan takziah korban bencana alam tanah longsor di Desa Mulyoarjo, Kecamatan Lawan.', 'respons', 'https://lh3.googleusercontent.com/d/1djqjpFC7apJeiDRY0a2iodY359sdWbtf', 'Minggu 7 Desember 2025 pukul 09.30 WIB. Kehadiran ini menjadi wujud kepedulian dan empati pemerintah Kabupaten Malang kepada keluarga korban serta masyarakat terdampak.
Turut mendampingi Sekretaris Daerah, Kepala Pelaksana BPBD, Kepala Dinas Sosial, Kepala Dinas Perumahan Kawasan Permukiman dan Cipta Karya, Kepala Dinas PU Bina Marga, Plt. Kepala Dinas PU Sumber Daya Air, Direktur Utama Perumda Tirta Kanjuruhan, serta Camat Lawang bersama Danramil, Kapolsek, TKSK, relawan, dan jajaran pimpinan serta staf Kecamatan Lawang.', '7 Desember 2025', 'Kecamatan Lawang', 'Humas Satgas Kencana', 2),
('1794381954721', 'Pemerintah Kecamatan Lawang Dampingi Penyaluran Bantuan Sosial untuk Warga Terdampak Bencana di Desa Mulyoarjo', 'respons', 'https://lh3.googleusercontent.com/d/1HetQAUAwOCLgicGsLVjvvBPprtlBtvN4', 'Sabtu, 06 Desember 2025 Pemerintah Kecamatan Lawang kembali hadir di tengah masyarakat yang terdampak bencana. Hari ini, pukul 14.00–16.00 WIB, Kepala Seksi Kesejahteraan Sosial Kecamatan Lawang, bersama Kasi Trantibum Kecamatan Lawang dan TKSK Lawang, melaksanakan monitoring dan fasilitasi penyaluran bantuan sosial di Desa Mulyoarjo.', '6 Desember 2025', 'Kecamatan Lawang', 'Humas Satgas Kencana', 3),
('1794381781820', 'Wujud Kepedulian Pemerintah, BPBD Kabupaten Malang Salurkan Bantuan Sosial di Kelurahan Kalirejo', 'respons', 'https://lh3.googleusercontent.com/d/1JjEMITGDwgy1PZ1kbuhPyUKHkfoJbuvK', 'Lawang – Selasa, 27 April 2025
Pemerintah Kabupaten Malang melalui Badan Penanggulangan Bencana Daerah (BPBD) menyalurkan bantuan sosial logistik kepada warga terdampak bencana di wilayah Kelurahan Kalirejo, Kecamatan Lawang. Penyaluran bantuan ini berlangsung pada Selasa (27/4) mulai pukul 13.00 hingga 16.00 WIB dan mendapatkan pendampingan langsung dari unsur Kecamatan Lawang dan Kelurahan Kalirejo.', '27 April 2025', 'Kecamatan Lawang', 'Humas Satgas Kencana', 4),
('1794381557554', 'PENYELENGGARAAN PROGRAM DESA TANGGUH BENCANA (DESTANA) TAHUN 2026 — KECAMATAN LAWANG', 'posko', 'https://lh3.googleusercontent.com/d/18GM6FDNu-LSQ8hGYt8ByYzOCom07r0AE', 'Kecamatan Lawang, Kabupaten Malang — Rabu, 6 Agustus 2026 🗓️
Kegiatan Penyelenggaraan Program Desa Tangguh Bencana (DESTANA) Tahun 2026 resmi dilaksanakan di Kecamatan Lawang. Program ini bertujuan membangun kesadaran, kesiapsiagaan, dan kemandirian masyarakat dalam menghadapi potensi bencana, sehingga desa mampu bertahan dan pulih dengan cepat apabila terjadi bencana.', '6 Agustus 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 5),
('1794381374812', 'Rapat Koordinasi Program KENCANA AWARD 2026', 'simulasi', 'https://lh3.googleusercontent.com/d/1v6TJWV2ijcGl9F7us0PAAJ3DOeKtzGM2', 'Pelaksanaan Rapat Koordinasi Program KENCANA AWARD 2026 secara daring bersama BPBD Kabupaten Malang, Selasa 20 Oktober 2026, membahas Indeks Ketangguhan Kecamatan (IKK) dan kategori juara, sebagai bentuk komitmen Kecamatan Lawang sebagai salah satu kecamatan peringkat 10 Besar.', '11 November 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 6),
('1794381034659', 'KECAMATAN LAWANG SIAP WUJUDKAN WILAYAH TANGGUH BENCANA MELALUI KENCANA AWARD 2026', 'simulasi', 'https://lh3.googleusercontent.com/d/14jxEC8oOzuiu9m5s0n30NsgtnsvocfIb', 'Lawang, Rabu, 28 Oktober 2026 — Pemerintah Kecamatan Lawang menerima kunjungan Tim Verifikasi Badan Penanggulangan Bencana Daerah (BPBD) Kabupaten Malang dalam rangka penilaian Kencana Award Tahun 2026.
Kegiatan ini menjadi momentum penting untuk mengevaluasi sekaligus memperkuat komitmen Kecamatan Lawang dalam mewujudkan wilayah yang tangguh terhadap bencana melalui kesiapsiagaan, mitigasi, serta keterlibatan aktif seluruh elemen masyarakat.', '28 November 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 7),
('1794310548592', 'Koordinasi Pemutakhiran Data Warga Negara di Daerah Rawan Bencana dan Korban Bencana Kecamatan Lawang Tahun 2026', 'mitigasi', 'https://lh3.googleusercontent.com/d/1HfgACjU_WQYpzdj9gf4R2dG6FnHK82vC', 'Rapat Koordinasi Pemutakhiran Data Warga Negara di Daerah Rawan Bencana dan Korban Bencana Kecamatan Lawang Tahun 2026, sebagai upaya meningkatkan akurasi data kebencanaan, memperkuat koordinasi lintas sektor, serta mendukung kesiapsiagaan dan penanggulangan bencana di wilayah Kecamatan Lawang.', '12 Oktober 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 8),
('1794300503375', '🌱 GERAKAN MALANG MELIJAU SUKSES DIGELAR DI SUMBER MLATEN KALIREJO 🌱', 'mitigasi', 'https://lh3.googleusercontent.com/d/14azTwWHnhuVC4t3ns6ELBP0N_GPPVGsj', 'LAWANG - Pemerintah Kecamatan Lawang bersama 170 peserta dari berbagai unsur sukses menggelar kegiatan Gerakan Bersama Masyarakat Lawang untuk Indonesia Asri dengan tema MALANG MELIJAU (Masyarakat Lawang Menanam, Melindungi & Menghijaukan) pada Sabtu (31/10/2026) Pukul 07.00 WIB di Lapangan Aset Pemprov Jatim, Sumber Mlaten RW 13 Kalirejo.
Kegiatan ini merupakan implementasi dari program KENCANA (Kecamatan Tangguh Bencana) dalam upaya menjaga kelestarian lingkungan dan mitigasi bencana melalui penghijauan.', '31 Oktober 2026', 'Kelurahan Kalirejo', 'Humas Satgas Kencana', 9),
('1794299397313', 'GEBER MALANG UNTUK INDONESIA ASRI - Gerakan Bersama Masyarakat Lawang Untuk Indonesia Aman, Sehat, Resik Dan Indah', 'inovasi', 'https://lh3.googleusercontent.com/d/1dcO5OTSGuTxpOo_zwNo_KHPQDjSvja73', 'Inovasi unggulan Kecamatan Lawang melalui Gerakan Bersama Masyarakat Lawang (GEBER) untuk mewujudkan lingkungan Aman, Sehat, Resik dan Indah. Dilaksanakan bersama Forkopimcam, Pemerintah Desa, relawan dan masyarakat di Dusun Mendek, Desa Srigading, 24 April 2026. Meliputi 5 gerakan: 1. Malang Bersih Bersih, 2. Malang Melijau (Menanam, Melindungi dan Menghijaukan Lingkungan), 3. Malang Berakal (Bersih Bersih Kali), 4. Malang Mamel (Memilah dan Mengolah Sampah), 5. Malang Skuter (Sekolah Ku Terbersih).', '24 April 2026', 'Desa Srigading', 'Humas Satgas Kencana', 10),
('1794294301568', 'MOBIL AMBULANCE DESA TURIREJO', 'respons', 'https://lh3.googleusercontent.com/d/1GJKY01VqyYiNuFkCXrpg-LmIo5JSMdUm', 'Ambulans Desa Turirejo Kecamatan Lawang, siap siaga 24/7 untuk evakuasi dan pelayanan kesehatan darurat. Terintegrasi dengan Posko Komando Utama Kecamatan Lawang - Kencana Award 2026', '07 Agustus 2026', 'Desa Turirejo - Kecamatan Lawang', 'Humas Satgas Kencana', 11),
('1794292001280', 'Penyelenggaraan Program DESTANA Tahun 2026 Kecamatan Lawang', 'posko', 'https://lh3.googleusercontent.com/d/18GM6FDNu-LSQ8hGYt8ByYzOCom07r0AE', 'Penyelenggaraan Program Desa Tangguh Bencana (DESTANA) Tahun 2026 di Kecamatan Lawang, 6 Agustus 2026. Meningkatkan kesadaran, kapasitas dan kesiapsiagaan masyarakat dalam menghadapi potensi bencana - Kencana Award 2026.', '6 Agustus 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 12),
('1794291003552', 'RAPAT KOORDINASI SATGAS KENCANA', 'simulasi', 'https://lh3.googleusercontent.com/d/1EyNNYZn8jDJxVZ7sjgY5Qx26X9SSvxMR', 'Rapat Koordinasi Satgas Kencana Kecamatan Lawang dalam rangka menyusun rencana program dan kegiatan menuju Kencana Award 2026.', '7 Agustus 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 13),
('1794283209080', 'MOBIL AMBULANCE DESA MULYOARJO', 'respons', 'https://lh3.googleusercontent.com/d/1ItDGjy4gy-28-0HV-lGm-pV01jwkG-ip', 'Ambulans Desa Mulyoarjo Kecamatan Lawang, siap siaga 24/7 untuk evakuasi dan pelayanan kesehatan darurat. Terintegrasi dengan Posko Komando Utama Kecamatan Lawang - Kencana Award 2026', '07 Agustus 2026', 'Desa Mulyoarjo', 'Humas Satgas Kencana', 14),
('1794282864647', 'MOBIL AMBULANCE DESA SIDOLUHUR', 'respons', 'https://lh3.googleusercontent.com/d/1gOUUl8g768UcZ8td85yFcw-Zd-qVWB5U', 'Ambulans Desa Sidoluhur Kecamatan Lawang, siap siaga 24/7 untuk evakuasi dan pelayanan kesehatan darurat. Terintegrasi dengan Posko Komando Utama Kecamatan Lawang - Kencana Award 2026', '07 Agustus 2026', 'Desa Sidoluhur', 'Humas Satgas Kencana', 15),
('1794282655932', 'MOBIL AMBULAN DESA SRIGADING', 'respons', 'https://lh3.googleusercontent.com/d/1YOcfqAtwpcNcgM2BLAgvjtJ5WBGptLRs', 'Ambulans Desa Srigading, siap siaga 24/7 untuk evakuasi dan pelayanan kesehatan darurat. Terintegrasi dengan Posko Komando Utama Kecamatan Lawang - Kencana Award 2026', '07 Agustus 2026', 'Desa Srigading (Zona Lereng)', 'Humas Satgas Kencana', 16),
('1794281601280', 'MOBIL AMBULAN PMI KECAMATAN LAWANG', 'respons', 'https://lh3.googleusercontent.com/d/10EWUIpvqbMjDJz0YvjifOLdWjk0QIwcI', 'Ambulance PMI Kecamatan Lawang, siap siaga 24/7 untuk evakuasi dan pelayanan kesehatan darurat. Terintegrasi dengan Posko Komando Utama Kecamatan Lawang - Kencana Award 2026.', '07 Agustus 2026', 'Kecamatan Lawang', 'Humas Satgas Kencana', 17),
('1', 'Rapat Koordinasi Satgas Kencana', 'simulasi', 'https://lh3.googleusercontent.com/d/1MN4lUtz2sGd-QAGI508gVz6V6imKh4Pf', 'Pembentukan struktur Satgas lintas sektor melibatkan Forkopimcam dan 12 Desa/Kelurahan guna memperkuat kerangka kerja terpadu penanggulangan bencana di wilayah Kecamatan Lawang.', '5 Agustus 2026', 'Aula Kantor Kecamatan Lawang', 'Humas Kecamatan Lawang', 18),
('2', 'Kerja Bakti Mitigasi Sungai & Tebing', 'mitigasi', 'https://lh3.googleusercontent.com/d/11PTjnmmX81rVC6o0lEactvZ9Iw7V66i_', 'Kegiatan kerja bakti ini menjadi salah satu bentuk kepedulian bersama terhadap kebersihan dan kelestarian lingkungan, khususnya kondisi sungai dan kawasan di sekitarnya.
Dalam pelaksanaannya, kegiatan melibatkan unsur Pemerintah Kecamatan Lawang, Pemerintah Desa Sidodadi, unsur TNI dan Polri, perangkat desa/kelurahan, instansi terkait, organisasi kemasyarakatan, dunia usaha, komunitas, serta masyarakat Desa Sidodadi.
Pembersihan saluran air dan normalisasi alur Kali Surak secara gotong royong bersama relawan dan warga untuk mencegah potensi banjir luapan di kawasan pemukiman padat.', '11 September 2026', 'Aliran Kali Surak Desa Sidodadi', 'Relawan Destana Lawang', 19),
('3', 'Simulasi Evakuasi & Uji EWS Digital', 'posko', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&q=80&w=900', 'Gladi kesiapsiagaan warga bersama relawan dan pengujian perangkat EWS digital real-time WhatsApp Gateway yang terhubung langsung dengan sensor pemantau curah hujan hulu Arjuno.', '08 Februari 2026', 'Dusun Krajan, Desa Srigading (Zona Lereng)', 'TRC Kencana Lawang', 20),
('4', 'Posko Komando Utama 24/7 Lawang', 'respons', 'https://lh3.googleusercontent.com/d/1Sj1igBcIZM9aVtnjGwlYO_gX1ua9Fnhw', 'Kesiapsiagaan Posko Komando fisik di Kantor Kecamatan Lawang (Jl. MH. Thamrin No. 2) lengkap dengan papan piket siaga 24 jam, sarpras darurat, serta armada ambulans desa.', '6 AGUSTUS 2026', 'Kantor Kecamatan Lawang', 'Piket Satgas Kecamatan', 21),
('5', 'Portal Pentahelix & Inovasi BNBA SATGAS / RELAWAN', 'inovasi', 'https://lh3.googleusercontent.com/d/1WstHS9_zz1BxUraNU0K-fQGPQIyB8FPL', 'Sistem pelaporan mandiri dan direktori darurat terintegrasi untuk layanan cepat warga serta pengelolaan data BNBA (By Name By Address) SATGAS/ RELAWAN', '28 Oktober 2026', 'Ruang Media Center Kencana Lawang', 'Tim IT Kencana Lawang', 22),
('6', '🌱 Langkah Sederhana, Dampak Besar: Warga Lawang Bersama Menanam untuk Negeri', 'mitigasi', 'https://lh3.googleusercontent.com/d/1wqAGKBD0KLPWBwQC1wSEI9mFjNTz_UaD', 'Semangat gotong royong kembali terasa di Kecamatan Lawang! Melalui gerakan GEBER MALANG, warga bersama Muspika, TNI-Polri, pemerintah desa/kelurahan, komunitas, hingga dunia usaha bersatu dalam aksi penanaman pohon di Desa Srigading (24/4/2026).
Bukan sekadar menanam pohon 🌳, kegiatan ini adalah wujud nyata kepedulian bersama untuk menjaga lingkungan tetap aman, sehat, resik, dan indah. Mengusung semangat MELIJAU (Merawat, Melindungi, dan Menghijaukan), langkah kecil hari ini menjadi investasi besar untuk masa depan.', '24 April 2026', 'Gunung Tumpuk Desa Srigading', 'Kader Konservasi Destana', 23),
('7', 'Gelar Peralatan SAR & Kesiapan Logistik', 'respons', 'https://lh3.googleusercontent.com/d/1MaOJe5q35kzPUFmlhFzPvH0xfZVg75XT', 'Pemeriksaan berkala kesiapan gergaji mesin (chainsaw), perahu karet evakuasi, tenda darurat, genset penerangan, dan peralatan P3K darurat di Posko Kecamatan Lawang.', '28 September 2026', 'Halaman Depan Kecamatan Lawang', 'Satpol PP & TRC Lawang', 24)
